-- Correctifs contenu du 2026-09-27 (AUDITS_LOG #21) : langage + réponses illogiques
-- 1) logique CE2 : 'X a rencontré un piano/poireau...' -> 'X a vu un ...'
-- 2) maths CP-CM2 : '1 + nom au pluriel' (1 perles, 1 heures, 1 euros...) -> singulier
-- 3) anglais CE1 : mots ambigus (vélo -> faire du vélo, pêche -> faire de la pêche, course -> la course à pied)
-- 4) anglais CM1 : 'mon sport préféré est natation' -> article ajouté
-- 5) anglais CM2 : 'I did golf/fishing...' -> I played / I went / I did selon le sport
-- 6) anglais CM1/CM2 : comparatifs incohérents (immeuble plus fort, rocher plus sec...) réécrits,
--    'higher' -> 'taller', 'leaf' -> 'sheet of paper', mauvais choix = variantes proches de la même phrase
-- Tout ou rien : chaque ligne est vérifiée sur son id ET son ancien énoncé ; si le compte ne correspond pas, RIEN n'est modifié.
begin;
create temp table tmp_correctifs (id integer primary key, ancien_enonce text not null, enonce text not null, bonne_reponse text not null, mauvais_choix text[] not null) on commit drop;

do $$
declare v_nb integer;
begin
	update contenu_questions q
	set enonce = t.enonce, bonne_reponse = t.bonne_reponse, mauvais_choix = t.mauvais_choix
	from tmp_correctifs t
	where q.id = t.id and q.enonce = t.ancien_enonce;
	get diagnostics v_nb = row_count;
	if v_nb <> 267 then
		raise exception 'ANNULÉ : % ligne(s) modifiée(s) au lieu de 267 (question déjà modifiée dans Studio ?)', v_nb;
	end if;
	raise notice 'OK : % questions corrigées', v_nb;
end $$;

-- Republication des paquets (seuls les paquets modifiés changent de version)
select fn_publier();

commit;
